package com.tencent.weknora.tenant;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.tencent.weknora.security.*;
import java.time.Instant;
import java.util.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class TenantService {
    private static final Logger LOG=LoggerFactory.getLogger(TenantService.class);
    private final JdbcTemplate jdbc;
    private final AuthRepository repository;
    private final TenantConfigurationCodec codec;
    private final ObjectMapper mapper;
    private final SecuritySettings settings;
    private final TransactionTemplate writes;
    public TenantService(JdbcTemplate jdbc,AuthRepository repository,TenantConfigurationCodec codec,ObjectMapper mapper,SecuritySettings settings,PlatformTransactionManager transactions){this.jdbc=jdbc;this.repository=repository;this.codec=codec;this.mapper=mapper;this.settings=settings;writes=new TransactionTemplate(transactions);writes.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    public Map<String,Object> current(AuthContext auth){if(auth.isApiKey())auth.requireCapability("manage_tenant_settings");return success(Map.of("items",List.of(project(load(auth.tenantId(),"Failed to retrieve workspace"),auth.role()))));}
    public Map<String,Object> detail(AuthContext auth,String id){long tenant=authorize(auth,id,"viewer");return success(project(load(tenant,"Failed to retrieve workspace"),auth.role()));}
    public Map<String,Object> all(AuthContext auth){catalog(auth);try{return success(Map.of("items",jdbc.queryForList("SELECT * FROM tenants WHERE deleted_at IS NULL ORDER BY created_at DESC").stream().map(row->project(row,"viewer")).toList()));}catch(DataAccessException ex){throw unavailable("Failed to retrieve all workspaces list");}}
    public Map<String,Object> search(AuthContext auth,String keyword,String id,String rawPage,String rawSize){catalog(auth);long tenant=queryId(id);long page=positive(rawPage,1);int size=(int)Math.min(100,positive(rawSize,20));List<Object> args=new ArrayList<>();List<String> filters=new ArrayList<>();if(tenant>0){filters.add("id=?");args.add(tenant);}if(keyword!=null&&!keyword.isEmpty()){String escaped=keyword.replace("\\","\\\\").replace("%","\\%").replace("_","\\_");filters.add("name LIKE ? ESCAPE '\\' OR description LIKE ? ESCAPE '\\'");args.add("%"+escaped+"%");args.add("%"+escaped+"%");}String where=" WHERE deleted_at IS NULL"+(filters.isEmpty()?"":" AND ("+String.join(" OR ",filters)+")");try{Long total=jdbc.queryForObject("SELECT COUNT(*) FROM tenants"+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var items=jdbc.queryForList("SELECT * FROM tenants"+where+" ORDER BY created_at DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(row->project(row,"viewer")).toList();return success(Map.of("items",items,"total",total==null?0L:total,"page",page,"page_size",size));}catch(DataAccessException ex){throw unavailable("Failed to search workspaces");}}
    public Map<String,Object> update(AuthContext auth,String id,String body){long tenant=authorize(auth,id,"owner");JsonNode root=codec.request(body);String name=pointer(root,"name",1,128),description=pointer(root,"description",0,512);if(name!=null){name=AuthPreferences.trimGoSpace(name);if(name.isEmpty())throw TenantConfigurationCodec.invalid("name cannot be blank");}if(description!=null)description=AuthPreferences.trimGoSpace(description);final String newName=name,newDescription=description;
        try{return writes.execute(status->{lock(tenant);recheck(auth,tenant,"owner");Map<String,Object> row=load(tenant,"Failed to load workspace");List<Object> args=new ArrayList<>();List<String> fields=new ArrayList<>();if(newName!=null){fields.add("name=?");args.add(newName);row.put("name",newName);}if(newDescription!=null){/* Go Updates(struct) skips empty strings but returns the mutated struct. */if(!newDescription.isEmpty()){fields.add("description=?");args.add(newDescription);}row.put("description",newDescription);}Instant now=Instant.now();fields.add("updated_at=?");args.add(repository.timestampParameter(now));args.add(tenant);jdbc.update("UPDATE tenants SET "+String.join(",",fields)+" WHERE id=? AND deleted_at IS NULL",args.toArray());row.put("updated_at",now.toString());return success(project(row,auth.role()));});}catch(DataAccessException ex){throw unavailable("Failed to update workspace");}}
    public Map<String,Object> config(AuthContext auth,String key){auth.requireRole("viewer");if(auth.isApiKey())auth.requireCapability("manage_tenant_settings");Map<String,Object> row=load(auth.tenantId(),"Workspace is empty");JsonNode root=mapper.valueToTree(repository.jsonValue(row.get(column(key))));return success(key.equals("memory-config")?codec.memory(root,false,true):codec.retrieval(root,false));}
    public Map<String,Object> updateConfig(AuthContext auth,String key,String body){auth.requireRole("admin");if(auth.isApiKey())auth.requireCapability("manage_tenant_settings");JsonNode root=codec.request(body);Map<String,Object> config=key.equals("memory-config")?codec.memory(root,true,true):codec.retrieval(root,true);String column=column(key);try{return writes.execute(status->{lock(auth.tenantId());recheck(auth,auth.tenantId(),"admin");jdbc.update("UPDATE tenants SET "+column+"="+repository.jsonParameter()+",updated_at=? WHERE id=? AND deleted_at IS NULL",repository.jsonString(config),repository.timestampParameter(Instant.now()),auth.tenantId());Map<String,Object> out=success(config);out.put("message",key.equals("memory-config")?"Memory configuration updated successfully":"Retrieval configuration updated successfully");return out;});}catch(DataAccessException ex){throw unavailable(key.equals("memory-config")?"Failed to update memory config":"Failed to update retrieval config");}}
    private Map<String,Object> project(Map<String,Object> row,String role){Map<String,Object> out=repository.publicTenant(row,role);if(row.get("retrieval_config")!=null)out.put("retrieval_config",codec.retrieval(mapper.valueToTree(repository.jsonValue(row.get("retrieval_config"))),false));if(row.get("memory_config")!=null)out.put("memory_config",codec.memory(mapper.valueToTree(repository.jsonValue(row.get("memory_config"))),false,false));return out;}
    private Map<String,Object> load(long tenant,String message){try{var rows=jdbc.queryForList("SELECT * FROM tenants WHERE id=? AND deleted_at IS NULL",tenant);if(rows.isEmpty())throw unavailable(message).withDetails("tenant not found");return new LinkedHashMap<>(rows.getFirst());}catch(DataAccessException ex){throw unavailable(message);}}
    private void lock(long tenant){if(jdbc.update("UPDATE tenants SET updated_at=updated_at WHERE id=? AND deleted_at IS NULL",tenant)!=1)throw unavailable("Failed to load workspace").withDetails("tenant not found");}
    private void recheck(AuthContext auth,long tenant,String required){if(auth.isApiKey()||auth.crossTenantSuperuser()||!auth.rbacEnforced())return;if(AuthContext.level(repository.role(auth.userId(),tenant))<AuthContext.level(required))throw new ApiException(403,"FORBIDDEN","Forbidden: insufficient workspace role");}
    private long authorize(AuthContext auth,String raw,String role){long id=pathId(raw);if(id!=auth.tenantId()&&!auth.crossTenantSuperuser())throw forbidden("Access denied: URL workspace does not match the active workspace");if(auth.isApiKey())throw forbidden("Forbidden: API key route is not migrated");auth.requireRole(role);return id;}
    private void catalog(AuthContext auth){if(!settings.crossTenantEnabled())throw forbidden("Cross-workspace access is disabled");if(auth.isApiKey()||!auth.crossTenantSuperuser())throw forbidden("Insufficient permissions for cross-workspace operation");}
    private static String column(String key){return switch(key){case "memory-config"->"memory_config";case "retrieval-config"->"retrieval_config";default->throw new ApiException(501,"NOT_MIGRATED","Configuration is not migrated");};}
    private static String pointer(JsonNode root,String key,int min,int max){JsonNode value=TenantConfigurationCodec.field(root,key);if(value==null||value.isNull())return null;if(!value.isTextual())throw TenantConfigurationCodec.invalid("Invalid request data");String text=value.textValue();int count=text.codePointCount(0,text.length());if(count<min||count>max)throw TenantConfigurationCodec.invalid("Invalid request data");return text;}
    private static long pathId(String raw){try{String id=AuthPreferences.trimGoSpace(raw);if(!id.matches("[0-9]+"))throw new NumberFormatException();long value=Long.parseLong(id);if(value<=0)throw new NumberFormatException();return value;}catch(Exception ex){throw TenantConfigurationCodec.invalid("workspace id must be a positive integer");}}
    private static long queryId(String raw){try{if(raw==null||!raw.matches("[0-9]+"))return 0;long value=Long.parseLong(raw);return Math.max(0,value);}catch(Exception ex){return 0;}}
    private static long positive(String raw,int fallback){try{long value=Long.parseLong(raw);return value<1?fallback:value;}catch(Exception ex){return fallback;}}
    private static Map<String,Object> success(Object data){Map<String,Object> out=new LinkedHashMap<>();out.put("success",true);out.put("data",data);return out;}
    private static ApiException forbidden(String message){return new ApiException(403,"FORBIDDEN",message).withAppCode(1002);}
    private static ApiException unavailable(String message){return new ApiException(500,"INTERNAL_ERROR",message).withAppCode(1007);}
    /** Role-denial audit uses the Go route template, with best-effort persistence after the request failed. */
    public void auditDenied(AuthContext auth,String rawPath,String template,String method,String role){try{boolean exists=false;try{Integer count=jdbc.queryForObject("SELECT COUNT(*) FROM audit_logs WHERE tenant_id=? AND actor_user_id=? AND action='rbac.access_denied' AND request_path=? AND created_at>=?",Integer.class,auth.tenantId(),auth.userId(),template,repository.timestampParameter(Instant.now().minusSeconds(60)));exists=count!=null&&count>0;}catch(DataAccessException ignored){}if(exists)return;Map<String,String> details=new LinkedHashMap<>();details.put("required_role",role);if(!rawPath.equals(template))details.put("raw_path",rawPath);writes.executeWithoutResult(status->jdbc.update("INSERT INTO audit_logs(tenant_id,actor_user_id,actor_role,action,request_path,request_method,outcome,details,created_at) VALUES(?,?,?,'rbac.access_denied',?,?,'denied',"+repository.jsonParameter()+",?)",auth.tenantId(),auth.userId(),auth.role(),template,method,repository.jsonString(details),repository.timestampParameter(Instant.now())));}catch(RuntimeException ex){LOG.warn("Unable to record denied tenant access");}}
}
